nta.declaration:
// Deterministic cut-in scenario with a 1 ms steering input vector.
// Time unit: millisecond.
// Distance unit: meter.
// Steering_Angle values: degrees.

const double PI = 3.141592653589793;
const int TOTAL_TIME = 20000;
const int CONTROL_PERIOD = 1;
const int LAST_INDEX = 20000;

const double EgoSpeed = 0.01388888888889; // 50 km/h in m/ms
const double WHEEL_BASE = 2.700000;

// Ego initial pose, used also by the SafetyShield committed initialization.
const double EGO_INITIAL_X = 300.0;
const double EGO_INITIAL_Y = 1.0;
const double EGO_INITIAL_HEADING = 0.0;

clock Time;


hybrid clock left_edge;
hybrid clock right_edge;
hybrid clock bottom_edge;
hybrid clock top_edge;

// Exact geometrically rotated shield corners.
// The local shield coordinates are longitudinal in [-rear, front]
// and lateral in [-lateral, lateral], rotated by ego heading.
hybrid clock shield_front_left_x, shield_front_left_y;
hybrid clock shield_front_right_x, shield_front_right_y;
hybrid clock shield_rear_left_x, shield_rear_left_y;
hybrid clock shield_rear_right_x, shield_rear_right_y;

// Exact geometrically rotated INNER shield corners.
// This is a tighter safety zone inside the main shield.
hybrid clock inner_shield_front_left_x, inner_shield_front_left_y;
hybrid clock inner_shield_front_right_x, inner_shield_front_right_y;
hybrid clock inner_shield_rear_left_x, inner_shield_rear_left_y;
hybrid clock inner_shield_rear_right_x, inner_shield_rear_right_y;

// Sampled longitudinal shield dimensions used between control updates.
hybrid clock front_shield_dist;
hybrid clock rear_shield_dist;
hybrid clock inner_front_shield_dist;
hybrid clock inner_rear_shield_dist;

// Vehicle states used by UPPAAL SMC.
hybrid clock x_pos;
hybrid clock y_pos;
hybrid clock heading;
hybrid clock rear_x, rear_y, slow_x, slow_y;


//For continuous speed changes, declare the surrounding-car speeds
hybrid clock rear_speed;
hybrid clock slow_speed;

double rear_acceleration = 0;
double slow_acceleration = 0;

// Current steering-vector index and current steering command.
int[0, LAST_INDEX] step = 0;
double steering = 0.0;


// Time is in seconds in the shield-distance equations
const double REACTION_TIME = 1.0;

// Minimum safety distances in meters
const double BASE_FRONT_GAP = 10.0;
const double BASE_REAR_GAP = 8.0;
const double BASE_LATERAL_GAP = 2.2;

// Fixed/initial shield dimensions in meters
const double FRONT_SHIELD = 20.0;
const double REAR_SHIELD = 15.0;
const double LATERAL_SHIELD = 2.2;

// Inner shield scaling. 0.5 means the inner shield is half of the main shield.
const double INNER_LONGITUDINAL_SCALE = 0.50;
const double INNER_LATERAL_SCALE = 0.50;

// Braking capabilities in m/s²
const double EGO_BRAKE = 6.0;
const double OTHER_BRAKE = 6.0;

//------- Variables to save data in text file------------
meta double T, X_Ego, Y_Ego, X_rear, Y_rear, X_slow, Y_slow,
    S_front_left_x, S_front_left_y,
    S_front_right_x, S_front_right_y,
    S_rear_right_x, S_rear_right_y,
    S_rear_left_x, S_rear_left_y,
    IS_front_left_x, IS_front_left_y,
    IS_front_right_x, IS_front_right_y,
    IS_rear_right_x, IS_rear_right_y,
    IS_rear_left_x, IS_rear_left_y;
//meta double T, X_Ego, Y_Ego, X_rear, Y_rear, X_slow, Y_slow,S_left_edge, S_right_edge,S_bottom_edge, S_top_edge;
meta int write_status = 0;
import "/Users/mnm01/UPPAAL_Model_cutin/mylib/myExLib.dylib" {
    int WriteVar(
        double T,
        double X_Ego,
        double Y_Ego,
        double X_rear,
        double Y_rear,
        double X_slow,
        double Y_slow,
        double S_front_left_x,
        double S_front_left_y,
        double S_front_right_x,
        double S_front_right_y,
        double S_rear_right_x,
        double S_rear_right_y,
        double S_rear_left_x,
        double S_rear_left_y,
        double IS_front_left_x,
        double IS_front_left_y,
        double IS_front_right_x,
        double IS_front_right_y,
        double IS_rear_right_x,
        double IS_rear_right_y,
        double IS_rear_left_x,
        double IS_rear_left_y
    );
};


double frontShieldDistance()
{
    double relative_speed;
    double braking_difference;

    relative_speed =
        fmax(0.0, EgoSpeed - slow_speed);

    braking_difference =
        fmax(0.0, 
            (EgoSpeed * EgoSpeed)
                / (2.0 * EGO_BRAKE)
            -
            (slow_speed * slow_speed)
                / (2.0 * OTHER_BRAKE)
        );

    return BASE_FRONT_GAP
        + relative_speed * REACTION_TIME
        + braking_difference;
}

double rearShieldDistance()
{
    double relative_speed;
    double braking_difference;

    relative_speed =
        fmax(0.0, rear_speed - EgoSpeed);

    braking_difference =
        fmax(0.0, 
            (rear_speed * rear_speed)
                / (2.0 * OTHER_BRAKE)
            -
            (EgoSpeed * EgoSpeed)
                / (2.0 * EGO_BRAKE)
        );

    return BASE_REAR_GAP
        + relative_speed * REACTION_TIME
        + braking_difference;
}


// Inner shield dimensions.
// They are computed as a scaled version of the main dynamic shield, so the
// inner shield always remains inside the main shield.
double innerFrontShieldDistance()
{
    return INNER_LONGITUDINAL_SCALE * frontShieldDistance();
}

double innerRearShieldDistance()
{
    return INNER_LONGITUDINAL_SCALE * rearShieldDistance();
}

double innerLateralShieldDistance()
{
    return INNER_LATERAL_SCALE * BASE_LATERAL_GAP;
}


// Ego yaw-rate in radians per millisecond.  The heading state is in radians.
double egoHeadingRate()
{
    return (EgoSpeed / WHEEL_BASE) * tan(steering * PI / 180.0);
}

// Convert a point from the ego local shield frame into world coordinates.
// longitudinal > 0 is in front of the ego; lateral > 0 is to the left.
double shieldCornerX(double longitudinal, double lateral)
{
    return x_pos
        + longitudinal * cos(heading)
        - lateral * sin(heading);
}

double shieldCornerY(double longitudinal, double lateral)
{
    return y_pos
        + longitudinal * sin(heading)
        + lateral * cos(heading);
}

// Time derivatives of the above coordinate transform for fixed sampled
// longitudinal/lateral dimensions over one CONTROL_PERIOD.
double shieldCornerXRate(double longitudinal, double lateral)
{
    return EgoSpeed * cos(heading)
        + egoHeadingRate()
            * (-longitudinal * sin(heading) - lateral * cos(heading));
}

double shieldCornerYRate(double longitudinal, double lateral)
{
    return EgoSpeed * sin(heading)
        + egoHeadingRate()
            * (longitudinal * cos(heading) - lateral * sin(heading));
}

// Axis-aligned bounding box of the rotated shield.  These functions preserve
// the old left/right/bottom/top variables as a conservative plotting/checking
// envelope, while the four shield_* corner pairs represent the exact geometry.
double rotatedShieldMinX(double front_dist, double rear_dist, double lateral)
{
    double fl;
    double fr;
    double rl;
    double rr;

    fl = shieldCornerX(front_dist, lateral);
    fr = shieldCornerX(front_dist, -lateral);
    rl = shieldCornerX(-rear_dist, lateral);
    rr = shieldCornerX(-rear_dist, -lateral);

    return fmin(fmin(fl, fr), fmin(rl, rr));
}

double rotatedShieldMaxX(double front_dist, double rear_dist, double lateral)
{
    double fl;
    double fr;
    double rl;
    double rr;

    fl = shieldCornerX(front_dist, lateral);
    fr = shieldCornerX(front_dist, -lateral);
    rl = shieldCornerX(-rear_dist, lateral);
    rr = shieldCornerX(-rear_dist, -lateral);

    return fmax(fmax(fl, fr), fmax(rl, rr));
}

double rotatedShieldMinY(double front_dist, double rear_dist, double lateral)
{
    double fl;
    double fr;
    double rl;
    double rr;

    fl = shieldCornerY(front_dist, lateral);
    fr = shieldCornerY(front_dist, -lateral);
    rl = shieldCornerY(-rear_dist, lateral);
    rr = shieldCornerY(-rear_dist, -lateral);

    return fmin(fmin(fl, fr), fmin(rl, rr));
}

double rotatedShieldMaxY(double front_dist, double rear_dist, double lateral)
{
    double fl;
    double fr;
    double rl;
    double rr;

    fl = shieldCornerY(front_dist, lateral);
    fr = shieldCornerY(front_dist, -lateral);
    rl = shieldCornerY(-rear_dist, lateral);
    rr = shieldCornerY(-rear_dist, -lateral);

    return fmax(fmax(fl, fr), fmax(rl, rr));
}

// Ego-frame coordinates of an arbitrary point, useful for collision/shield tests.
double shieldLocalLongitudinal(double px, double py)
{
    double dx;
    double dy;

    dx = px - x_pos;
    dy = py - y_pos;

    return dx * cos(heading) + dy * sin(heading);
}

double shieldLocalLateral(double px, double py)
{
    double dx;
    double dy;

    dx = px - x_pos;
    dy = py - y_pos;

    return -dx * sin(heading) + dy * cos(heading);
}

bool pointInsideRotatedShield(double px, double py, double front_dist, double rear_dist, double lateral)
{
    double longitudinal;
    double lateral_coord;

    longitudinal = shieldLocalLongitudinal(px, py);
    lateral_coord = shieldLocalLateral(px, py);

    return longitudinal >= -rear_dist
        && longitudinal <= front_dist
        && lateral_coord >= -lateral
        && lateral_coord <= lateral;
}

bool rearInsideRotatedShield()
{
    return pointInsideRotatedShield(
        rear_x,
        rear_y,
        front_shield_dist,
        rear_shield_dist,
        BASE_LATERAL_GAP
    );
}

bool slowInsideRotatedShield()
{
    return pointInsideRotatedShield(
        slow_x,
        slow_y,
        front_shield_dist,
        rear_shield_dist,
        BASE_LATERAL_GAP
    );
}

bool rotatedShieldViolation()
{
    if (Time<=0)
    {
    return false;}
    else{
    return rearInsideRotatedShield() || slowInsideRotatedShield();}   
}


bool rearInsideInnerShield()
{
    return pointInsideRotatedShield(
        rear_x,
        rear_y,
        inner_front_shield_dist,
        inner_rear_shield_dist,
        innerLateralShieldDistance()
    );
}

bool slowInsideInnerShield()
{
    return pointInsideRotatedShield(
        slow_x,
        slow_y,
        inner_front_shield_dist,
        inner_rear_shield_dist,
        innerLateralShieldDistance()
    );
}

bool innerShieldViolation()
{
    return rearInsideInnerShield() || slowInsideInnerShield();
}


void SaveVar()
{
    write_status = WriteVar(
        T,
        X_Ego,
        Y_Ego,
        X_rear,
        Y_rear,
        X_slow,
        Y_slow,
        S_front_left_x,
        S_front_left_y,
        S_front_right_x,
        S_front_right_y,
        S_rear_right_x,
        S_rear_right_y,
        S_rear_left_x,
        S_rear_left_y,
        IS_front_left_x,
        IS_front_left_y,
        IS_front_right_x,
        IS_front_right_y,
        IS_rear_right_x,
        IS_rear_right_y,
        IS_rear_left_x,
        IS_rear_left_y
    );
}
void UpdateVar()
{
    T=Time; 
    X_Ego = x_pos;
    Y_Ego = y_pos;
    X_rear = rear_x;
    Y_rear = rear_y;
    X_slow = slow_x;
    Y_slow = slow_y;

    // Main rotated shield corners
    S_front_left_x = shield_front_left_x;
    S_front_left_y = shield_front_left_y;
    S_front_right_x = shield_front_right_x;
    S_front_right_y = shield_front_right_y;
    S_rear_right_x = shield_rear_right_x;
    S_rear_right_y = shield_rear_right_y;
    S_rear_left_x = shield_rear_left_x;   
    S_rear_left_y = shield_rear_left_y;

    // Inner rotated shield corners
    IS_front_left_x = inner_shield_front_left_x;
    IS_front_left_y = inner_shield_front_left_y;
    IS_front_right_x = inner_shield_front_right_x;
    IS_front_right_y = inner_shield_front_right_y;
    IS_rear_right_x = inner_shield_rear_right_x;
    IS_rear_right_y = inner_shield_rear_right_y;
    IS_rear_left_x = inner_shield_rear_left_x;
    IS_rear_left_y = inner_shield_rear_left_y;

    SaveVar();
}

template.declaration:
const double initialSpeed= 0.01389;  // 50 km/h is exactly 0.01389 meters per millisecond (m/ms).
clock Orientation;  // orientation of the car
const int Steering_Angle = 0;

const double initialSpeed= 0.01389;  // 50 km/h is exactly 0.01389 meters per millisecond (m/ms).
clock Orientation;  // orientation of the car
const int Steering_Angle = 0;
